  --closeflow-stage158-overlay-portal-density-source-truth: "active";

  /* Inherit Stage157 zoom when available. */
  --cf158-overlay-scale: var(--cf157-page-zoom, 0.80);
  --cf158-overlay-inverse-scale: var(--cf157-page-zoom-inverse, 1.25);

  --cf158-overlay-radius: 18px;
  --cf158-overlay-padding: 20px;
  --cf158-overlay-gap: 12px;

  --cf158-overlay-max-width: calc(100vw * var(--cf158-overlay-inverse-scale) - 48px);
  --cf158-overlay-max-height: calc(100vh * var(--cf158-overlay-inverse-scale) - 48px);

  --cf158-overlay-font-body: 13px;
  --cf158-overlay-font-title: 20px;
  --cf158-overlay-font-label: 12px;
  --cf158-overlay-control-height: 36px;
}

