  --cf159-dialog-radius: 18px;
  --cf159-dialog-pad-x: 24px;
  --cf159-dialog-pad-y: 18px;
  --cf159-dialog-gap: 12px;

  --cf159-form-gap: 10px;
  --cf159-field-gap: 6px;
  --cf159-control-height: 34px;
  --cf159-control-pad-x: 12px;

  --cf159-font-title: 20px;
  --cf159-font-body: 13px;
  --cf159-font-label: 12px;
  --cf159-font-small: 11px;

  --cf159-footer-height: 58px;
  --cf159-footer-pad-y: 10px;
}

