.stage217-case-service-panel,
.stage217-case-notes-panel {
  overflow: hidden;
}

.stage217-case-service-actions,
.stage217-case-notes-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.stage217-case-service-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-top: 16px;
}

.stage217-case-service-card {
  min-height: 132px;
  border: 1px solid rgba(100, 116, 139, 0.16);
  border-radius: 20px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.94));
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.06);
  padding: 16px;
}

.stage217-case-service-card--next {
  border-color: rgba(59, 130, 246, 0.22);
  background: linear-gradient(180deg, rgba(239, 246, 255, 0.96), rgba(255, 255, 255, 0.94));
}

.stage217-case-service-card--blockers {
  border-color: rgba(245, 158, 11, 0.26);
  background: linear-gradient(180deg, rgba(255, 251, 235, 0.96), rgba(255, 255, 255, 0.94));
}

.stage217-case-service-card--workload {
  border-color: rgba(16, 185, 129, 0.2);
  background: linear-gradient(180deg, rgba(236, 253, 245, 0.96), rgba(255, 255, 255, 0.94));
}

.stage217-case-service-card--finance {
  border-color: rgba(124, 58, 237, 0.18);
  background: linear-gradient(180deg, rgba(245, 243, 255, 0.96), rgba(255, 255, 255, 0.94));
}

.stage217-case-service-card__label {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.07em;
  margin-bottom: 8px;
  text-transform: uppercase;
}

.stage217-case-service-card h3 {
  color: #0f172a;
  font-size: 16px;
  font-weight: 850;
  line-height: 1.2;
  margin: 0 0 8px;
}

.stage217-case-service-card p {
  color: #475569;
  font-size: 13px;
  line-height: 1.5;
  margin: 0;
}

.stage217-case-service-card__metric {
  color: #0f172a;
  display: block;
  font-size: 24px;
  font-weight: 900;
  line-height: 1;
  margin-bottom: 8px;
}

.stage217-case-work-section {
  border-top: 1px solid rgba(148, 163, 184, 0.18);
  margin-top: 16px;
  padding-top: 16px;
}

.stage217-case-work-section__head {
  align-items: flex-end;
  display: flex;
  gap: 12px;
  justify-content: space-between;
  margin-bottom: 12px;
}

.stage217-case-work-section__head h3 {
  color: #0f172a;
  font-size: 15px;
  font-weight: 850;
  margin: 0 0 4px;
}

.stage217-case-work-section__head p {
  color: #64748b;
  font-size: 12px;
  margin: 0;
}

.stage217-case-notes-list {
  display: grid;
  gap: 10px;
  margin-top: 16px;
}

.stage217-case-note-row {
  border: 1px solid rgba(99, 102, 241, 0.14);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 14px 32px rgba(15, 23, 42, 0.05);
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 12px;
  padding: 14px;
}

.stage217-case-note-row__icon {
  align-items: center;
  background: rgba(99, 102, 241, 0.08);
  border-radius: 12px;
  color: #4f46e5;
  display: inline-flex;
  height: 36px;
  justify-content: center;
  width: 36px;
}

.stage217-case-note-row time {
  color: #64748b;
  display: block;
  font-size: 11px;
  font-weight: 750;
  margin-bottom: 6px;
}

.stage217-case-note-row p {
  color: #1f2937;
  font-size: 13px;
  line-height: 1.55;
  margin: 0;
  white-space: pre-wrap;
}

.stage217-case-history-row p[data-stage217-note-summary='true'] {
  color: #64748b;
  font-style: italic;
}

@media (max-width: 1180px) {
  .stage217-case-service-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .stage217-case-service-grid {
    grid-template-columns: 1fr;
  }

  .stage217-case-service-actions,
  .stage217-case-notes-actions,
  .stage217-case-work-section__head {
    align-items: stretch;
    flex-direction: column;
  }
}

