/* STAGE34_CALENDAR_READABILITY_STATUS_FORMS
   Mobile/desktop readability lock for Calendar month/week entries and form fields.
   Scope: Calendar route and Radix calendar/task/event dialogs only.
*/

.main[data-current-section="kalendarz"],
.main [data-calendar-stage34],
.view[data-calendar-stage34] {
  overflow-x: clip;
}

/* Month/week entries: stop hiding the useful part of the title. */
.main[data-current-section="kalendarz"] .truncate,
.main[data-current-section="kalendarz"] [class*="truncate"] {
  overflow: visible !important;
  text-overflow: clip !important;
  white-space: normal !important;
  min-width: 0 !important;
}

.main[data-current-section="kalendarz"] button,
.main[data-current-section="kalendarz"] a {
  min-width: 0;
}

/* Calendar pills in the month grid. Keep the chip look, but allow two readable lines. */
.main[data-current-section="kalendarz"] [class*="rounded-full"][class*="border"] {
  max-width: 100%;
}

.main[data-current-section="kalendarz"] [class*="rounded-full"][class*="border"] span,
.main[data-current-section="kalendarz"] [class*="rounded-full"][class*="border"] p,
.main[data-current-section="kalendarz"] [class*="rounded-full"][class*="border"] strong {
  min-width: 0;
  overflow-wrap: anywhere;
}

/* Month day cards may grow a little instead of turning entries into unreadable scraps. */
.main[data-current-section="kalendarz"] [class*="grid"] > [class*="rounded"] {
  min-width: 0;
}

.main[data-current-section="kalendarz"] [class*="calendar-month"],
.main[data-current-section="kalendarz"] [data-calendar-month],
.main[data-current-section="kalendarz"] [data-calendar-view="month"] {
  max-width: 100%;
  overflow-x: clip;
