.main[data-current-section="kalendarz"] .calendar-entry-completed,
.main[data-current-section="kalendarz"] [data-calendar-entry-completed="true"] {
  opacity: 0.62 !important;
  filter: grayscale(0.15);
}

.main[data-current-section="kalendarz"] .calendar-entry-completed,
.main[data-current-section="kalendarz"] .calendar-entry-completed *,
.main[data-current-section="kalendarz"] [data-calendar-entry-completed="true"],
.main[data-current-section="kalendarz"] [data-calendar-entry-completed="true"] * {
  text-decoration: line-through !important;
  text-decoration-thickness: 2px !important;
