/* CLIENT_CASE_FORMS_VISUAL_REBUILD_STAGE23 */

.client-case-form-content {
  width: min(780px, calc(100vw - 24px)) !important;
  max-width: 780px !important;
  max-height: min(92vh, 900px);
  overflow: hidden;
  border: 1px solid #e4e7ec !important;
  border-radius: 28px !important;
  background: rgba(255, 255, 255, 0.96) !important;
  color: #111827 !important;
  box-shadow: 0 24px 70px rgba(16, 24, 40, 0.16) !important;
  padding: 0 !important;
}

.client-case-form-content::before,
.client-case-form-content::after,
.client-case-form::before,
.client-case-form::after,
.client-case-form-section::before,
.client-case-form-section::after {
  content: none !important;
  display: none !important;
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
}

.client-case-form-header {
  border-bottom: 1px solid #e4e7ec;
  background:
    radial-gradient(circle at top left, rgba(37, 99, 235, 0.08), transparent 34%),
    #ffffff;
  padding: 22px 24px 18px;
}

.client-case-form-kicker {
  display: block;
  margin-bottom: 8px;
  color: #2563eb;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.14em;
}

.client-case-form-header h2 {
  color: #111827;
  font-size: 24px;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.client-case-form-header p {
  margin: 8px 0 0;
  color: #667085;
  font-size: 13px;
  line-height: 1.5;
}

.client-case-form {
  max-height: calc(92vh - 110px);
  overflow-y: auto;
  padding: 18px 24px 22px;
  display: grid;
  gap: 14px;
  background: #f9fafb;
}

.client-case-form-section {
  border: 1px solid #e4e7ec;
  border-radius: 24px;
  background: #ffffff;
  color: #111827;
  box-shadow: 0 8px 22px rgba(16, 24, 40, 0.05);
