  font-size: 15px;
  font-weight: 850;
  letter-spacing: -0.02em;
}

.client-case-form-section-head p,
.client-case-form-hint {
  margin: 5px 0 0;
  color: #667085;
  font-size: 12px;
  line-height: 1.5;
}

.client-case-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.client-case-form-field {
  display: grid;
  gap: 7px;
}

.client-case-form-field-wide {
  grid-column: 1 / -1;
}

.client-case-form-field label {
  color: #475467;
  font-size: 12px;
  font-weight: 800;
}

.client-case-form input,
.client-case-form-select,
.client-case-form textarea,
.client-case-form-textarea {
  width: 100%;
  min-height: 42px;
  border: 1px solid #e4e7ec !important;
  border-radius: 18px !important;
  background: #ffffff !important;
  color: #111827 !important;
  padding: 10px 13px;
  font-size: 14px;
  outline: none;
  box-shadow: 0 4px 12px rgba(16, 24, 40, 0.03);
}

.client-case-form input:focus,
.client-case-form-select:focus,
.client-case-form textarea:focus,
.client-case-form-textarea:focus {
  border-color: #93c5fd !important;
