  border-radius: 16px;
  background: #fff;
  color: #111827;
  padding: 10px 12px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  text-align: left;
}

.client-case-form-suggestions strong,
.client-case-form-locked-client strong {
  display: block;
  color: #111827;
  font-size: 13px;
  font-weight: 850;
}

.client-case-form-suggestions small,
.client-case-form-locked-client span {
  display: block;
  margin-top: 3px;
  color: #667085;
  font-size: 12px;
  line-height: 1.4;
}

.client-case-form-locked-client,
.client-case-form-inline-client,
.client-case-form-disabled-note {
  border: 1px solid #e4e7ec;
  border-radius: 20px;
  background: #eff6ff;
  color: #111827;
  padding: 13px;
}

.client-case-form-locked-client button {
  margin-top: 10px;
  width: fit-content;
  border: 1px solid #bfdbfe;
  border-radius: 999px;
  background: #fff;
  color: #1d4ed8;
  min-height: 32px;
  padding: 6px 10px;
  font-size: 12px;
  font-weight: 850;
}

.client-case-form-inline-client {
  background: #f9fafb;
}

.client-case-form-inline-client p {
  margin: 0 0 10px;
  color: #111827;
  font-size: 13px;
  font-weight: 850;
}

.client-case-form-disabled-note {
  background: #fffaeb;
  border-color: #fedf89;
  color: #475467;
  font-size: 12px;
  line-height: 1.5;
}

.client-case-form-footer {
  position: sticky;
  bottom: -22px;
  border-top: 1px solid #e4e7ec;
  background: rgba(255, 255, 255, 0.94);
  padding: 14px 0 0;
  gap: 10px;
}

.client-case-form-footer button {
  width: auto !important;
  min-height: 42px;
  border-radius: 16px;
  font-weight: 800;
}

/* Detail edit forms get the same light treatment without touching logic. */
.client-detail-edit-field,
.client-detail-contact-repeat-row,
.case-detail-edit-field,
.case-detail-form-field {
  color: #111827;
}

.client-detail-edit-field input,
.client-detail-contact-repeat-row input,
.client-detail-edit-field textarea,
.case-detail-edit-field input,
.case-detail-form-field input,
.case-detail-edit-field textarea,
.case-detail-form-field textarea,
.case-detail-edit-field select,
.case-detail-form-field select {
  border: 1px solid #e4e7ec !important;
  border-radius: 18px !important;
  background: #fff !important;
  color: #111827 !important;
  box-shadow: 0 4px 12px rgba(16, 24, 40, 0.03) !important;
}

@media (max-width: 640px) {
  .client-case-form-content {
    width: calc(100vw - 16px) !important;
    max-height: 94vh;
    border-radius: 24px !important;
  }

  .client-case-form-header {
    padding: 18px 16px 14px;
  }

  .client-case-form {
    max-height: calc(94vh - 98px);
    padding: 14px;
  }

  .client-case-form-grid,
  .client-case-form-client-row {
    grid-template-columns: 1fr;
  }

  .client-case-form-field-wide {
    grid-column: auto;
  }

  .client-case-form-footer {
    display: grid !important;
    grid-template-columns: 1fr;
  }

  .client-case-form-footer button {
    width: 100% !important;
  }
}
