.today-pipeline-value-card {
  position: relative;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--app-border) 76%, transparent) !important;
  border-radius: 1.5rem !important;
  background:
    radial-gradient(circle at top right, color-mix(in srgb, var(--color-primary) 16%, transparent), transparent 16rem),
    var(--app-surface-strong) !important;
  color: var(--app-text) !important;
  box-shadow: 0 18px 48px var(--app-shadow-color) !important;
}

.today-pipeline-value-card::before {
  content: "";
